// Oxford Geography adventures. Every screen manipulates a place, model, route or created artefact.
const GX_TYPES={atlas:'Atlas reconstruction',expedition:'Compass expedition',watershed:'Flood defence laboratory',city:'Settlement planner',cargo:'Supply-chain challenge',cycle:'Water-drop journey',landform:'Landscape sculptor',studio:'Geography creation studio',chronicle:'Time-travel museum',fieldwork:'Fieldwork investigation'};
const gxIs=q=>q?.geo?.kind?.startsWith('gx-');
function gxFields(q){const k=q.geo.kind.slice(3),t=JSON.parse(JSON.stringify(q.geo.task||{}));gpAssert(Object.hasOwn(GX_TYPES,k),'Choose a Geography adventure.');gpText(t.brief,1400);gpText(t.check,1000);gpAssert(JSON.stringify(t).length<30000,'Keep an adventure under 30 KB.');
 const numbers=(a,min,max,count)=>{gpArray(a,count||1,count||40).forEach(v=>gpNumber(v,min,max));};
 if(k==='atlas'){gpAssert(Object.hasOwn(GEO_BOARDS,t.board),'Choose an atlas backdrop.');gpArray(t.landmarks,2,8).forEach(x=>gpText(x,100));}
 if(k==='expedition'){numbers(t.blocked,0,29);numbers(t.stops,0,29);gpAssert(t.stops.length<=6&&new Set(t.stops).size===t.stops.length,'Use at most six distinct expedition stations.');gpNumber(t.start,0,29);gpNumber(t.goal,0,29);gpNumber(t.fuel,1,60);gpArray(t.discoveries,t.stops.length,t.stops.length).forEach(x=>gpText(x,250));gpAssert(![t.start,t.goal,...t.stops].some(n=>t.blocked.includes(n)),'Keep the expedition start, finish and stations accessible.');const queue=[[t.start,0,0]],seen=new Set();let possible=false;while(queue.length){const [n,c,m]=queue.shift(),key=n+':'+m;if(c>t.fuel||seen.has(key))continue;seen.add(key);if(n===t.goal&&m===(1<<t.stops.length)-1){possible=true;break;}for(const next of gpNeighbours(n))if(!t.blocked.includes(next))queue.push([next,c+1,m|(t.stops.includes(next)?1<<t.stops.indexOf(next):0)]);}gpAssert(possible,'The route needs enough fuel to visit all stations and finish.');}
 if(['watershed','city'].includes(k)){numbers(t.homes,0,29);numbers(t.protected,0,29);gpNumber(t.budget,1,40);gpAssert(!t.homes.some(n=>t.protected.includes(n)),'Homes cannot also be protected land.');if(k==='watershed'){numbers(t.elevation,0,8,30);numbers(t.storms,1,8);gpNumber(t.trees,0,5);}else gpNumber(t.radius,1,5);}
 if(k==='cargo'){gpArray(t.nodes,4,8).forEach(x=>gpText(x,65));gpArray(t.edges,3,14).forEach(e=>{numbers(e,0,30,4);gpNumber(e[0],0,t.nodes.length-1);gpNumber(e[1],0,t.nodes.length-1);gpNumber(e[2],1,10);gpNumber(e[3],1,10);});numbers(t.required,0,t.nodes.length-1);gpNumber(t.money,1,40);gpNumber(t.freshness,1,40);gpNumber(t.goal,1,t.nodes.length-1);}
 if(k==='cycle'){numbers(t.required,0,5);gpNumber(t.start,0,5);gpNumber(t.goal,0,5);}
 if(k==='landform'){numbers(t.profile,0,5,6);gpNumber(t.height,1,5);gpText(t.process,100);}
 if(k==='studio'){gpArray(t.notes,2,8).forEach(x=>gpText(x,260));gpArray(t.rubric,2,5).forEach(x=>gpText(x,180));gpAssert(['casefile','storyboard','sketch'].includes(t.style),'Choose a creation-studio layout.');}
 if(k==='chronicle'){gpArray(t.steps,4,8).forEach(x=>gpText(x,150));gpAssert(new Set(t.steps).size===t.steps.length,'Use unique museum captions.');gpAssert(Object.hasOwn(GEO_BOARDS,t.board),'Choose a museum backdrop.');}
 if(k==='fieldwork'){numbers(t.readings,0,20,9);numbers(t.zones,0,2,9);gpText(t.unit,50);gpAssert([0,1,2].every(z=>t.zones.filter(v=>v===z).length>=2),'Provide at least two stations in each zone.');}
 return {geo:{kind:q.geo.kind,source:String(q.geo.source||t.brief).slice(0,1800),task:t},options:[],answer:t.check};
}
const gxPreviousFields=geoFields;geoFields=q=>gxIs(q)?gxFields(q):gxPreviousFields(q);
function gxState(q){const t=q.geo.task;return {tool:q.geo.kind==='gx-city'?'water':q.geo.kind==='gx-landform'?'scrape':q.geo.kind==='gx-studio'?'pen':'wall',selected:null,placements:{},turns:[1,2,3,1,2,3],deck:shuffle([0,1,2,3,4,5]),peek:false,path:[t.start??0],builds:{},result:null,tested:false,spent:0,chilled:false,travelTime:0,freshness:t.freshness||0,store:t.start||0,visited:[t.start||0],journal:[],heights:Array(24).fill(t.height??5),strokes:[],notes:{},caption:'',review:false,order:[],samples:[],bars:[0,0,0],notice:'',tries:0,undo:[]};}
const gxPreviousRound=geoRound;geoRound=l=>{gxPreviousRound(l);const q=game.items[l.index];if(gxIs(q)){l.gx=gxState(q);l.gx.deck=shuffle(Array.from({length:q.geo.task.steps?.length||6},(_,i)=>i));l.choices=[];l.tiles=[];}};
function gxButton(i,a,label,n='',attrs='',disabled=false){return geoButton(i,'gx-'+a,label,'data-value="'+n+'" '+attrs,disabled);}
function gxMapTile(board,n,rotation=0){const body=geoBackdrop(GEO_BOARDS[board].background).replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'');return '<svg viewBox="'+(n%3*200)+' '+(Math.floor(n/3)*165)+' 200 165" aria-hidden="true" style="transform:rotate('+rotation*90+'deg)">'+body+'</svg>';}
function gxIcon(type){const paths={home:'M5 14L20 2 35 14V35H5z M16 35V22H24V35',tree:'M20 1L3 22H12L6 30H17V39H23V30H34L28 22H37z',wall:'M2 18H38V38H2z M2 28H38 M12 18V28 M28 28V38',water:'M20 0C18 9 5 18 5 26A15 15 0 0035 26C35 18 22 9 20 0',clinic:'M4 8H36V36H4z M15 13H25V19H31V27H25V33H15V27H9V19H15z',bus:'M6 4H34V31H6z M10 9H30V20H10z M10 35H13 M27 35H30',park:'M20 2L2 26H38z M20 24V39',evacuate:'M2 18H25V7L39 21 25 35V24H2z',channel:'M0 8Q10 0 20 8T40 8V31Q30 23 20 31T0 31z'};return '<svg class="gx-icon" viewBox="0 0 40 42" aria-hidden="true"><path d="'+(paths[type]||paths.home)+'" fill="currentColor" fill-rule="evenodd" stroke="currentColor" stroke-linejoin="round" stroke-width="2"/></svg>';}
function gxBoard(i,t,s,type){return '<div class="gx-land-board">'+Array.from({length:30},(_,n)=>{const river=n%6===2,home=t.homes.includes(n),built=s.builds[n],unsafe=s.result?.damaged?.includes(n);return gxButton(i,'build',(river?gxIcon('water'):'')+(home?gxIcon('home'):'')+(built?gxIcon(built):'')+'<small>'+String.fromCharCode(65+n%6)+(Math.floor(n/6)+1)+'</small>',n,'class="gx-land-cell '+(river?'gx-river-cell ':'')+(home?'gx-home ':'')+(t.protected.includes(n)?'gx-protected ':'')+(unsafe?'gx-flooded':'')+'" aria-label="'+(home?'Homes at ':t.protected.includes(n)?'Protected land at ':'Build at ')+String.fromCharCode(65+n%6)+(Math.floor(n/6)+1)+'"');}).join('')+'</div>';}
const GX_CYCLE_EDGES=[[0,1,'Evaporate','☀'],[1,2,'Condense','☁'],[2,3,'Rain onto soil','🌧'],[2,0,'Rain into ocean','🌊'],[3,4,'Root uptake','🌱'],[4,1,'Transpire','🍃'],[3,5,'Runoff','🏞'],[5,0,'River flow','➜']];
function gxSceneUI(i,q,l){const t=q.geo.task,s=l.gx,k=q.geo.kind.slice(3),B=(a,label,n='',attrs='',disabled=false)=>gxButton(i,a,label,n,attrs,disabled);
 if(k==='atlas')return '<div class="gx-atlas-tools">'+B('peek',s.peek?'Hide reference':'Study the atlas')+B('rotate','Rotate selected piece ↻','', '',s.selected===null)+'<span>Rebuild all six fragments. North points up.</span></div>'+(s.peek?'<div class="gx-atlas-reference">'+geoBackdrop(GEO_BOARDS[t.board].background)+'</div>':'<div class="gx-jigsaw">'+Array.from({length:6},(_,n)=>B('slot',s.placements[n]===undefined?'<span class="gx-empty">'+(n+1)+'</span>':gxMapTile(t.board,s.placements[n],s.turns[s.placements[n]]),n,'data-gx-drop="1" class="gx-piece-slot" aria-label="Atlas slot '+(n+1)+'"')).join('')+'</div>')+'<div class="gx-piece-tray">'+s.deck.filter(n=>!Object.values(s.placements).includes(n)).map(n=>B('piece',gxMapTile(t.board,n,s.turns[n]),n,'data-gx-drag="1" class="gx-piece" aria-label="Map fragment '+(n+1)+'" aria-pressed="'+(s.selected===n)+'"')).join('')+'</div><p class="gx-caption">'+esc(t.landmarks.join(' · '))+'</p>';
 if(k==='expedition'){const at=s.path.at(-1);return '<div class="gx-expedition-layout"><div class="gx-route-board">'+Array.from({length:30},(_,n)=>'<div class="gx-route-cell '+(t.blocked.includes(n)?'gx-mountain':s.path.includes(n)?'gx-trail':'')+'"><small>'+String.fromCharCode(65+n%6)+(Math.floor(n/6)+1)+'</small>'+(n===at?'<span class="gx-rover">🧭</span>':n===t.goal?'🏁':t.stops.includes(n)?(s.path.includes(n)?'✓':'🔬'):t.blocked.includes(n)?'▲':n%7===0?'🌲':'')+'</div>').join('')+'</div><div class="gx-compass"><strong>N ↑</strong>'+B('move','↑ North',-6)+B('move','← West',-1)+B('move','East →',1)+B('move','↓ South',6)+'<b>Fuel: '+(t.fuel-s.path.length+1)+'</b><span>Stations: '+t.stops.filter(n=>s.path.includes(n)).length+'/'+t.stops.length+'</span></div></div><p class="gx-caption">'+esc(s.notice||'Use the compass to travel around the mountains. Visit every research station before the flag.')+'</p>';}
 if(k==='watershed'||k==='city'){const costs=k==='watershed'?{wall:3,tree:2,evacuate:2,channel:2}:{water:2,clinic:3,bus:2,park:1},names={wall:'Flood wall',tree:'Wetland trees',evacuate:'Evacuation',channel:'Storage basin',water:'Water point',clinic:'Clinic',bus:'Bus stop',park:'Green space'};return '<div class="gx-build-tools">'+Object.entries(costs).map(([key,cost])=>B('tool',gxIcon(key)+'<span>'+names[key]+' · '+cost+'</span>',key,'aria-pressed="'+(s.tool===key)+'"')).join('')+B('tool','↶ Remove','remove','aria-pressed="'+(s.tool==='remove')+'"')+'<b>Budget '+s.spent+'/'+t.budget+'</b></div>'+gxBoard(i,t,s,k)+'<div class="gx-sim-result">'+B('simulate',k==='watershed'?'Run both storms 🌧':'Open the services 🏘')+'<span>'+esc(s.result?.summary||(k==='watershed'?'Prepare the town, then watch the flood test.':'Bring water and healthcare within reach of every home.'))+'</span></div>';}
 if(k==='cargo'){const at=s.path.at(-1),positions=t.nodes.map((_,n)=>[70+(n%3)*230,50+Math.floor(n/3)*140]);return '<div class="gx-cargo-scene"><svg viewBox="0 0 600 350" preserveAspectRatio="none" aria-hidden="true">'+t.edges.map(([a,b,c,time])=>'<path d="M'+positions[a].join(' ')+' L'+positions[b].join(' ')+'" stroke="'+(s.path.some((n,j)=>j&&s.path[j-1]===a&&n===b)?'#e3ae42':'#abc4ce')+'" stroke-width="6" stroke-dasharray="9 5"/>').join('')+'</svg><div class="gx-cargo-nodes">'+t.nodes.map((name,n)=>B('travel','<span>'+(at===n?'🚚':s.path.includes(n)?'✓':'📦')+'</span><b>'+esc(name)+'</b>'+t.edges.filter(e=>e[0]===at&&e[1]===n).map(e=>'<small>'+e[2]+' coins · '+e[3]+' hours</small>').join(''),n,'class="'+(at===n?'gx-here':'')+'"',n!==at&&!t.edges.some(e=>e[0]===at&&e[1]===n))).join('')+'</div></div><div class="gx-cargo-hud"><b>Coins '+(t.money-s.spent)+'</b><b>Freshness '+s.freshness+'</b><b>Travel '+s.travelTime+' h</b>'+B('chill',s.chilled?'Cooling installed':'Buy cooling · 2 coins','', '',s.chilled)+'</div>';}
 if(k==='cycle'){const names=['Ocean','Water vapour','Cloud','Soil','Plant','River'],icons=['🌊','☀️','☁️','🟫','🌳','🏞️'];return '<div class="gx-cycle-stores">'+names.map((name,n)=>'<div class="'+(s.store===n?'gx-water-here':'')+'">'+icons[n]+'<b>'+name+'</b>'+(s.store===n?'<span class="gx-droplet">💧</span>':'')+'<small>'+s.visited.filter(v=>v===n).length+' visits</small></div>').join('')+'</div><div class="gx-cycle-controls">'+GX_CYCLE_EDGES.map(([a,b,name,icon],n)=>B('transfer',icon+' '+name,n,'',s.store!==a)).join('')+'</div><div class="gx-water-journal">'+(s.journal.length?s.journal.map(n=>esc(GX_CYCLE_EDGES[n][2])).join(' → '):'Your water-drop journey will be recorded here.')+'</div>';}
 if(k==='landform'){return '<div class="gx-build-tools">'+B('tool','Abrasion · scrape 1','scrape','aria-pressed="'+(s.tool==='scrape')+'"')+B('tool','Pluck a block · remove 2','pluck','aria-pressed="'+(s.tool==='pluck')+'"')+B('tool','Deposit · add 1','deposit','aria-pressed="'+(s.tool==='deposit')+'"')+'<span>'+esc(t.process)+'</span></div><div class="gx-relief" data-gx-surface="relief"><svg viewBox="0 0 620 280" aria-label="Sculptable landscape">'+s.heights.map((h,n)=>{const c=n%6,r=Math.floor(n/6),x=125+c*64-r*27,y=125+r*29-h*15;return '<g data-mode-action="geo-gx-sculpt" data-lane="'+i+'" data-value="'+n+'" tabindex="0" role="button" aria-label="Rock cell '+(n+1)+', height '+h+'"><path d="M'+x+' '+y+'l56 0 24 20-56 0z" fill="'+['#76c6de','#dbcc95','#bdc481','#9caf72','#769866','#577f5e'][h]+'" stroke="#efffe1" stroke-width="2"/><path d="M'+x+' '+y+'v'+(h*15)+'l24 20v-'+(h*15)+'z" fill="#698a76"/><path d="M'+(x+24)+' '+(y+20)+'h56v'+(h*15)+'h-56z" fill="#a6b47f"/></g>';}).join('')+'</svg><div class="gx-sculpt-grid" aria-label="Landscape height controls">'+s.heights.map((h,n)=>B('sculpt',String(h),n,'aria-label="Rock cell '+(n+1)+', height '+h+'"')).join('')+'</div></div><div class="gx-target-profile"><b>Target section</b><svg viewBox="0 0 300 70" aria-hidden="true"><path d="M'+t.profile.map((v,n)=>(20+n*50)+' '+(65-v*11)).join(' L')+'" stroke="#2e687a" stroke-width="7" fill="none"/></svg><span>'+t.profile.join(' · ')+' height units</span></div>';}
 if(k==='studio'){return '<div class="gx-studio-tools">'+B('tool','✎ Draw / connect','pen','aria-pressed="'+(s.tool==='pen')+'"')+B('tool','⌫ Erase last stroke','erase')+'<label>Caption <input data-gx-caption="'+i+'" maxlength="240" placeholder="Write your claim or map caption" value="'+esc(s.caption)+'"></label></div><div class="gx-studio-board" data-gx-surface="ink"><svg viewBox="0 0 600 240" preserveAspectRatio="none" aria-label="Geography '+t.style+' canvas">'+(t.style==='storyboard'?'<path d="M200 0V240M400 0V240" stroke="#b8c6c4" stroke-dasharray="7 5"/><text x="20" y="23">Before</text><text x="220" y="23">Change</text><text x="420" y="23">Consequence</text>':t.style==='sketch'?'<path d="M0 200Q160 70 310 140T600 70" stroke="#b4e1ec" stroke-width="35" fill="none"/>':'<circle cx="300" cy="120" r="100" fill="none" stroke="#d3decc" stroke-dasharray="5 8"/>')+s.strokes.map(points=>'<polyline points="'+points.map(p=>p.join(',')).join(' ')+'" stroke="#23597d" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" fill="none"/>').join('')+Object.entries(s.notes).map(([n,p])=>'<g transform="translate('+p[0]+' '+p[1]+')"><circle r="17" fill="#f0bf52"/><text y="6" text-anchor="middle" font-size="18">'+(Number(n)+1)+'</text></g>').join('')+'</svg></div><div class="gx-note-tray">'+t.notes.map((text,n)=>B('note','<b>'+(n+1)+'</b> Drag evidence marker',n,'title="'+esc(text)+'" data-gx-drag="1" aria-pressed="'+(s.selected===n)+'"')).join('')+'</div>'+(s.review?'<div class="gx-teacher-review"><strong>Teacher / partner review</strong><p>'+t.rubric.map(esc).join(' · ')+'</p>'+B('approve','Work meets the brief')+B('keepworking','Continue creating')+'</div>':'');}
 if(k==='chronicle'){return '<div class="gx-museum-scene">'+geoBackdrop(GEO_BOARDS[t.board].background)+'<div class="gx-museum-clock">⏳ '+Object.keys(s.placements).length+'/'+t.steps.length+' exhibits</div></div><div class="gx-time-rail">'+t.steps.map((_,n)=>B('slot',s.placements[n]===undefined?'<b>'+(n+1)+'</b><span>Place exhibit here</span>':'<b>'+(n+1)+'</b><span>'+esc(t.steps[s.placements[n]])+'</span>',n,'data-gx-drop="1" class="gx-exhibit"')).join('')+'</div><div class="gx-exhibit-tray">'+s.deck.filter(n=>!Object.values(s.placements).includes(n)).map(n=>B('piece',esc(t.steps[n]),n,'data-gx-drag="1" aria-pressed="'+(s.selected===n)+'"')).join('')+'</div>';}
 if(k==='fieldwork'){return '<div class="gx-fieldwork-layout"><div class="gx-field-stations">'+t.readings.map((v,n)=>B('sample','<span>'+['🌳','🏘️','🏔️'][t.zones[n]]+'</span><b>Site '+(n+1)+'</b><small>'+(s.samples.includes(n)?v+' '+esc(t.unit):'Collect reading')+'</small>',n,'class="gx-zone-'+t.zones[n]+'" aria-pressed="'+s.samples.includes(n)+'"')).join('')+'</div><div class="gx-field-chart">'+[0,1,2].map(z=>'<section><b>Zone '+String.fromCharCode(65+z)+'</b><div class="gx-field-bar"><i style="height:'+s.bars[z]*5+'%"></i><strong>'+s.bars[z]+'</strong></div>'+B('bar','−',z,'data-change="-1"')+B('bar','+',z,'data-change="1"')+'</section>').join('')+'</div></div><p class="gx-caption">Collect two samples per zone. Set each bar to that zone’s mean, rounded to a whole number. Selected readings: '+s.samples.map(n=>'site '+(n+1)+' = '+t.readings[n]).join('; ')+'</p>';}
 return '';
}
function gxPanel(i){const l=game.session.lanes[i],q=game.items[l.index],s=l.gx,t=q.geo.task;return '<div class="geo-panel-head"><strong>'+esc(l.name)+'</strong></div><p>Geography adventure</p><h2>'+esc(q.prompt)+'</h2><details class="gx-brief"><summary>Mission & evidence</summary><p>'+esc(t.brief)+'</p><p>'+esc(q.geo.source)+'</p>'+(t.notes?'<ol>'+t.notes.map(n=>'<li>'+esc(n)+'</li>').join('')+'</ol>':'')+'</details><div class="gx-task gx-'+q.geo.kind.slice(3)+'">'+gxSceneUI(i,q,l)+'</div><p class="gx-status" role="status">'+esc(s.notice||"Open Mission & evidence for the goal. Build, test and revise your work.")+'</p><div class="gx-toolbar">'+gxButton(i,'undo','Undo')+gxButton(i,'reset','Restart mission')+gxButton(i,'check',q.geo.kind==='gx-studio'?'Review my creation':'Complete mission')+gxButton(i,'finish','Teacher review / finish')+'</div>';}
const gxPreviousPanel=geoPanelHTML;geoPanelHTML=i=>{const l=game.session.lanes[i],q=game.items[l.index];if(!gxIs(q))return gxPreviousPanel(i);if(l.phase==='question')return gxPanel(i);if(l.phase==='feedback')return '<div class="geo-panel-head"><strong>'+esc(l.name)+'</strong></div><p>Adventure review</p><div class="gx-feedback"><span>'+(l.good?'🏆':'🔎')+'</span><h2>'+(l.good?'Mission accomplished':'Compare and improve')+'</h2><p>'+l.score+' points · '+esc(GX_TYPES[q.geo.kind.slice(3)])+'</p><details open><summary>Discuss the model</summary><p>'+esc(q.geo.task.check)+'</p></details></div>'+geoButton(i,'next',l.index===game.items.length-1?'Finish adventure →':'Next adventure →');return gxPreviousPanel(i);};
function gxOutcome(k,t,s){if(k==='atlas')return Array.from({length:6},(_,n)=>s.placements[n]===n&&s.turns[n]%4===0).every(Boolean);if(k==='chronicle')return t.steps.every((_,n)=>s.placements[n]===n);if(k==='expedition')return s.path.at(-1)===t.goal&&t.stops.every(n=>s.path.includes(n))&&s.path.length-1<=t.fuel;if(k==='watershed')return s.tested&&s.result.damaged.length===0&&Object.values(s.builds).filter(v=>v==='tree').length>=t.trees;if(k==='city')return s.tested&&s.result.served===t.homes.length&&Object.values(s.builds).includes('park');if(k==='cargo')return s.path.at(-1)===t.goal&&t.required.every(n=>s.path.includes(n))&&s.freshness>0&&s.spent<=t.money;if(k==='cycle')return s.store===t.goal&&t.required.every(n=>s.visited.includes(n))&&s.journal.length>=5;if(k==='landform')return s.heights.every((v,n)=>v===t.profile[n%6]);if(k==='studio')return s.strokes.length>=2&&Object.keys(s.notes).length>=2&&s.caption.trim().length>=5;if(k==='fieldwork')return [0,1,2].every(z=>{const a=s.samples.filter(n=>t.zones[n]===z);return a.length===2&&s.bars[z]===Math.round(a.reduce((v,n)=>v+t.readings[n],0)/2);});return false;}
function gxSimulate(k,t,s){if(k==='watershed'){const forest=Object.values(s.builds).filter(v=>v==='tree').length,storage=Object.values(s.builds).filter(v=>v==='channel').length,level=Math.max(...t.storms),damaged=t.homes.filter(n=>{const local=s.builds[n];return local!=='evacuate'&&t.elevation[n]+(local==='wall'?3:0)+Math.min(2,forest)+Math.min(2,storage)<level;});s.result={damaged,summary:(t.homes.length-damaged.length)+'/'+t.homes.length+' neighbourhoods protected in both storms · '+forest+' wetland plots'};}else {const distance=(a,b)=>Math.abs(a%6-b%6)+Math.abs(Math.floor(a/6)-Math.floor(b/6)),served=t.homes.filter(n=>{const bus=Object.entries(s.builds).some(([p,v])=>v==='bus'&&distance(n,Number(p))<=1);return ['water','clinic'].every(kind=>Object.entries(s.builds).some(([p,v])=>v===kind&&distance(n,Number(p))<=t.radius+(bus?1:0)));}).length;s.result={served,summary:served+'/'+t.homes.length+' neighbourhoods can reach water and healthcare'};}s.tested=true;}
function gxComplete(i,good){const l=game.session.lanes[i],penalty=good?Math.min(80,l.gx.tries*10):0;l.lastGain=good?100-penalty:0;geoScore(i,good);if(penalty){l.score-=penalty;game.score-=penalty;}geoPaint(i);}
const gxPreviousHandle=geoHandle;geoHandle=b=>{if(!b.dataset.modeAction?.startsWith('geo-gx-'))return gxPreviousHandle(b);const i=Number(b.dataset.lane),l=game?.session?.lanes?.[i];if(!l||l.phase!=='question'||game.done||ui.view!=='player'||b.disabled||game.session.review||game.session.mode==='TEAM'&&game.session.active!==i)return;const q=game.items[l.index];if(!gxIs(q))return;const k=q.geo.kind.slice(3),t=q.geo.task,s=l.gx,a=b.dataset.modeAction.slice(7),n=Number(b.dataset.value),valid=(x,max)=>Number.isInteger(x)&&x>=0&&x<max;
 if(a==='check'){if(gxOutcome(k,t,s)){if(k==='studio'){s.review=true;geoPaint(i);}else gxComplete(i,true);}else{s.tries++;s.notice=k==='studio'?'Add at least two drawn connections, two evidence markers and a caption before requesting review.':'Keep investigating. '+t.brief;geoPaint(i);}return;}
 if(a==='approve'&&k==='studio'&&s.review&&gxOutcome(k,t,s)){gxComplete(i,true);return;}if(a==='finish'){gxComplete(i,false);return;}if(a==='reset'){const tries=s.tries;l.gx=gxState(q);l.gx.tries=tries;l.gx.deck=shuffle(Array.from({length:t.steps?.length||6},(_,n)=>n));geoPaint(i);return;}if(a==='undo'){const previous=s.undo.pop();if(previous){const tries=s.tries,undo=s.undo;l.gx={...JSON.parse(previous),tries,undo};geoPaint(i);}return;}const before=JSON.stringify({...s,undo:undefined});let changed=true;
 if(a==='piece'&&['atlas','chronicle'].includes(k)&&valid(n,k==='atlas'?6:t.steps.length))s.selected=n;
 else if(a==='rotate'&&k==='atlas'&&s.selected!==null)s.turns[s.selected]=(s.turns[s.selected]+1)%4;
 else if(a==='peek'&&k==='atlas')s.peek=!s.peek;
 else if(a==='slot'&&['atlas','chronicle'].includes(k)&&valid(n,k==='atlas'?6:t.steps.length)){if(s.selected===null){s.selected=s.placements[n]??null;delete s.placements[n];}else{for(const key of Object.keys(s.placements))if(s.placements[key]===s.selected)delete s.placements[key];s.placements[n]=s.selected;s.selected=null;}}
 else if(a==='move'&&k==='expedition'&&[-6,-1,1,6].includes(n)){const at=s.path.at(-1),next=at+n;if(gpNeighbours(at).includes(next)&&!t.blocked.includes(next)&&s.path.length-1<t.fuel){s.path.push(next);const station=t.stops.indexOf(next);s.notice=station>=0?t.discoveries[station]:'';}else s.notice='That route is blocked or you have used your fuel. Undo to change course.';}
 else if(a==='tool'){s.tool=b.dataset.value;if(s.tool==='erase'){s.strokes.pop();s.tool='pen';}}
 else if(a==='build'&&['watershed','city'].includes(k)&&valid(n,30)){const costs=k==='watershed'?{wall:3,tree:2,evacuate:2,channel:2}:{water:2,clinic:3,bus:2,park:1};if(s.tool==='remove'){if(s.builds[n])s.spent-=costs[s.builds[n]];delete s.builds[n];s.tested=false;}else if(Object.hasOwn(costs,s.tool)){const home=t.homes.includes(n),allowed=!t.protected.includes(n)&&(k==='watershed'?(['wall','evacuate'].includes(s.tool)?home:!home):!home);const cost=s.spent-(costs[s.builds[n]]||0)+costs[s.tool];if(allowed&&cost<=t.budget){s.spent=cost;s.builds[n]=s.tool;s.tested=false;s.result=null;s.notice='';}else s.notice='Check the budget and site: keep protected land clear; place services on open land, and walls or evacuation at homes.';}}
 else if(a==='simulate'&&['watershed','city'].includes(k))gxSimulate(k,t,s);
 else if(a==='travel'&&k==='cargo'&&valid(n,t.nodes.length)){const edge=t.edges.find(e=>e[0]===s.path.at(-1)&&e[1]===n);if(edge&&s.spent+edge[2]<=t.money&&s.freshness>0){s.spent+=edge[2];s.travelTime+=edge[3];s.freshness=Math.max(0,s.freshness-Math.ceil(edge[3]/(s.chilled?2:1)));s.path.push(n);}else s.notice='This connection is unavailable or outside the remaining budget.';}
 else if(a==='chill'&&k==='cargo'&&!s.chilled&&s.spent+2<=t.money){s.chilled=true;s.spent+=2;}
 else if(a==='transfer'&&k==='cycle'&&valid(n,GX_CYCLE_EDGES.length)&&GX_CYCLE_EDGES[n][0]===s.store){s.store=GX_CYCLE_EDGES[n][1];s.visited.push(s.store);s.journal.push(n);}
 else if(a==='sculpt'&&k==='landform'&&valid(n,24)&&['scrape','pluck','deposit'].includes(s.tool))s.heights[n]=Math.max(0,Math.min(5,s.heights[n]+(s.tool==='deposit'?1:s.tool==='pluck'?-2:-1)));
 else if(a==='note'&&k==='studio'&&valid(n,t.notes.length))s.selected=n;
 else if(a==='place-note'&&k==='studio'&&s.selected!==null){const x=Number(b.dataset.x),y=Number(b.dataset.y);if(Number.isFinite(x)&&Number.isFinite(y)){s.notes[s.selected]=[Math.max(20,Math.min(580,x)),Math.max(25,Math.min(220,y))];s.selected=null;}}
 else if(a==='keepworking'&&k==='studio')s.review=false;
 else if(a==='sample'&&k==='fieldwork'&&valid(n,9)){if(s.samples.includes(n))s.samples=s.samples.filter(v=>v!==n);else if(s.samples.filter(v=>t.zones[v]===t.zones[n]).length<2)s.samples.push(n);else s.notice='Two sites are already sampled in this zone. Tap one to replace it.';}
 else if(a==='bar'&&k==='fieldwork'&&valid(n,3)&&[-1,1].includes(Number(b.dataset.change)))s.bars[n]=Math.max(0,Math.min(20,s.bars[n]+Number(b.dataset.change)));
 else changed=false;if(changed){s.undo=[...s.undo,before].slice(-80);geoPaint(i);}
};
const gxGestures=new Map(),gxClicks=new Map();
function gxFire(el){if(el?.dataset.modeAction)geoHandle(el);}
function gxSurfacePoint(el,e){const r=el.getBoundingClientRect();return [(e.clientX-r.left)/r.width*600,(e.clientY-r.top)/r.height*240];}
document.addEventListener('pointerdown',e=>{const panel=e.target.closest('[data-geo-panel]');if(!panel)return;const i=Number(panel.dataset.geoPanel),drag=e.target.closest('[data-gx-drag]'),surface=e.target.closest('[data-gx-surface]');if(!drag&&!surface){gxClicks.delete(i);return;}const l=game?.session?.lanes?.[i];if(!l?.gx||l.phase!=='question'||game.session.mode==='TEAM'&&game.session.active!==i)return;e.preventDefault();gxClicks.set(i,Date.now()+500);const g={i,owner:game.session,drag:!!drag,surface:surface?.dataset.gxSurface,last:null,points:[]};gxGestures.set(e.pointerId,g);if(drag)gxFire(drag);else if(g.surface==='relief'){const b=e.target.closest('[data-mode-action]');g.last=b?.dataset.value;gxFire(b);}else {g.points=[gxSurfacePoint(surface,e)];g.before=JSON.stringify({...l.gx,undo:undefined});}},{passive:false});
document.addEventListener('pointermove',e=>{const g=gxGestures.get(e.pointerId);if(!g||g.owner!==game?.session)return;const hit=document.elementFromPoint(e.clientX,e.clientY),p=hit?.closest('[data-geo-panel]');if(Number(p?.dataset.geoPanel)!==g.i)return;if(g.surface==='ink'){const surface=p.querySelector('[data-gx-surface="ink"]');g.points.push(gxSurfacePoint(surface,e));let path=surface.querySelector('.gx-live-ink');if(!path){path=document.createElementNS('http://www.w3.org/2000/svg','polyline');path.setAttribute('class','gx-live-ink');path.setAttribute('stroke','#23597d');path.setAttribute('stroke-width','4');path.setAttribute('fill','none');surface.querySelector('svg').append(path);}path.setAttribute('points',g.points.map(p=>p.join(',')).join(' '));}else if(g.surface==='relief'){const b=hit?.closest('[data-mode-action]');if(b&&b.dataset.value!==g.last){g.last=b.dataset.value;gxFire(b);}}},{passive:false});
document.addEventListener('pointerup',e=>{const g=gxGestures.get(e.pointerId);if(!g)return;gxGestures.delete(e.pointerId);if(g.owner!==game?.session)return;const l=game.session.lanes[g.i],hit=document.elementFromPoint(e.clientX,e.clientY),panel=hit?.closest('[data-geo-panel]');if(Number(panel?.dataset.geoPanel)!==g.i){geoPaint(g.i);return;}const surface=panel.querySelector('[data-gx-surface="ink"]');if(g.drag){const slot=hit.closest('[data-gx-drop]');if(slot)gxFire(slot);else if(surface&&surface.contains(hit)){const [x,y]=gxSurfacePoint(surface,e);geoHandle({dataset:{modeAction:'geo-gx-place-note',lane:String(g.i),x:String(x),y:String(y)}});}}else if(g.surface==='ink'){if(l.gx.selected!==null){const [x,y]=gxSurfacePoint(surface,e);geoHandle({dataset:{modeAction:'geo-gx-place-note',lane:String(g.i),x:String(x),y:String(y)}});}else if(g.points.length>2){l.gx.strokes.push(g.points);l.gx.undo.push(g.before);geoPaint(g.i);}}gxClicks.set(g.i,Date.now()+500);});
document.addEventListener('pointercancel',e=>{const g=gxGestures.get(e.pointerId);gxGestures.delete(e.pointerId);if(g&&g.owner===game?.session)geoPaint(g.i);});document.addEventListener('click',e=>{const b=e.target.closest('[data-mode-action^="geo-gx-"]');if(b&&e.detail>0&&(gxClicks.get(Number(b.dataset.lane))||0)>Date.now()){e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('input',e=>{if(e.target.matches('[data-gx-caption]')){const l=game?.session?.lanes?.[Number(e.target.dataset.gxCaption)];if(l?.phase==='question'&&l.gx)l.gx.caption=e.target.value;}});
document.addEventListener('keydown',e=>{if(e.target.matches('g[data-mode-action="geo-gx-sculpt"]')&&['Enter',' '].includes(e.key)){e.preventDefault();gxFire(e.target);}});
